  }

  markDirty(row: number): void {
    if (this.isShared) {
      Atomics.store(this.dirtyRows, row, 1);
    } else {
      this.dirtyRows[row] = 1;
    }
  }

  /** Mark a contiguous range of rows [from..to] dirty. */
  markDirtyRange(from: number, to: number): void {
