  isDirty(row: number): boolean {
    if (this.isShared) {
      return Atomics.load(this.dirtyRows, row) !== 0;
    }
    return this.dirtyRows[row] !== 0;
  }

  clearDirty(row: number): void {
    if (this.isShared) {
      Atomics.store(this.dirtyRows, row, 0);
    } else {
      this.dirtyRows[row] = 0;
    }
