// Skia throws on a color it can't parse; the renderer emits hex + rgb(), but
// guard anyway so a stray value can't crash the native surface.
const VALID_COLOR_RE = /^(#[0-9a-fA-F]{3,8}|rgba?\([^)]*\)|transparent)$/;
