                const font = selectFont(cmd.bold, cmd.italic);
                if (!font) return null;
                return (
                  <SkiaText
                    key={i}
                    x={cmd.x}
                    y={cmd.y}
                    text={cmd.text}
                    font={font}
                    color={safeColor(cmd.color, coreTheme.foreground)}
